/// Which keychain field holds a runtime preset's secret, keyed by its declared auth method (#1235).
#[cfg(feature = "source-stage")]
pub(crate) fn runtime_secret_field(auth: &str) -> &'static str {
    match auth {
        "basic" => "password",
        "apikey" => "apiKey",
        "token" => "token",
        _ => "accessToken", // oauth
    }
}
